//! 📜️ Individually authored Procedure parent and independently addressed child handles.
use super::ProcedureSnapshot;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound}}};
#[path="📏️native/🦀️.rs"]mod native;
impl ArtifactSqliteSnapshot for ProcedureSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{if Self::SQLITE_SCHEMA.len()>c.limits().max_schema_bytes{return Err("Procedure authored SQL exceeds schema byte limit".into())}c.check_rows(3)?;store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),super::ProcedurePackRecord::__dsl_spec_producer(),|record,control|super::ProcedurePackRecord::__dsl_from_record_controlled(record,control)?.into_snapshot_controlled(control),c)}
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{if Self::SQLITE_SCHEMA.len()>c.limits().max_schema_bytes{return Err("Procedure authored SQL exceeds schema byte limit".into())}c.check_rows(3)?;store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),super::ProcedurePackRecord::__dsl_spec_producer(),|control|super::ProcedurePackRecord::snapshot_record_controlled(self,control).map_err(|message|store::TextError::new(message,dsl::TextSpan::at(1,1))),c)}
 fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;p.check_rows(3)?;p.insert("procedure_document",&[Cell::Text(&self.schema)])?;let f=&self.flow;let ft=&f.target;let fd=&ft.dialect;p.insert("procedure_flow_child",&[Cell::Text(&f.child_id),Cell::Text(&ft.artifact_id),Cell::Text(&fd.artifact_kind),Cell::Text(&fd.standard),Cell::Text(&fd.subset)])?;let t=&self.text;let tt=&t.target;let td=&tt.dialect;p.insert("procedure_text_child",&[Cell::Text(&t.child_id),Cell::Text(&tt.artifact_id),Cell::Text(&td.artifact_kind),Cell::Text(&td.standard),Cell::Text(&td.subset)])?;p.finish()}
 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let p=d.table("procedure_document")?.single_row()?;let f=d.table("procedure_flow_child")?.single_row()?;let t=d.table("procedure_text_child")?.single_row()?;if p.rowid!=1||f.rowid!=1||t.rowid!=1||p.integer(0)?!=1||f.integer(0)?!=1||t.integer(0)?!=1||p.values.len()!=2||f.values.len()!=6||t.values.len()!=6{return Err("Procedure requires exact identity-1 parent and child rows".into())}let mut r=Reconstruction::new(c)?;let schema=r.text(p.text(1)?)?;let flow=store::ArtifactChild::new(r.text(f.text(1)?)?,store::os_io::ArtifactRef{artifact_id:r.text(f.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:r.text(f.text(3)?)?,standard:r.text(f.text(4)?)?,subset:r.text(f.text(5)?)?}});let text=store::ArtifactChild::new(r.text(t.text(1)?)?,store::os_io::ArtifactRef{artifact_id:r.text(t.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:r.text(t.text(3)?)?,standard:r.text(t.text(4)?)?,subset:r.text(t.text(5)?)?}});r.checkpoint()?;Ok(Self{schema,flow,text})}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=NativeEncodingBound::new(c)?;b.add(8192)?;b.repeated(self.schema.len(),16)?;let f=&self.flow;let ft=&f.target;let fd=&ft.dialect;let t=&self.text;let tt=&t.target;let td=&tt.dialect;for text in[&f.child_id,&ft.artifact_id,&fd.artifact_kind,&fd.standard,&fd.subset,&t.child_id,&tt.artifact_id,&td.artifact_kind,&td.standard,&td.subset]{b.repeated(text.len(),16)?}native::local_scenes(self,&mut b)?;b.finish()}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;if dialect.artifact_kind!="s.imperative.procedure"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("Procedure dialect differs from its owned wildcard").into())}if d.table("procedure_document")?.single_row()?.text(1)?!=self.schema{return Err(String::from("Procedure projected schema differs").into())}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(store::io_schema::IoOutcome::clean(()))}
 fn retire_sqlite_snapshot(mut self){use neural_engine::ColdRetire;if let Some(owner)=self.flow.take_local_owner::<crate::ProcedureFlowWorkingData>().expect("Procedure flow owner type"){drop(std::sync::Arc::into_inner(owner));}if let Some(owner)=self.text.take_local_owner::<crate::ProcedureTextWorkingData>().expect("Procedure text owner type"){if let Some(data)=std::sync::Arc::into_inner(owner){data.seed.retire_cold();}}}
}
